from datetime import datetime

MONTHS = {"jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
          "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12}

def parse_user_date(text):
    text = text.strip()
    for fmt in ("%Y-%m-%d", "%Y-%m-%d %H:%M"):
        try:
            return datetime.strptime(text, fmt), fmt
        except ValueError:
            pass
    parts = text.replace(",", " ").split()
    if len(parts) == 3:
        a, b, c = parts
        if a.lower()[:3] in MONTHS:      # Nov 26 2026
            return datetime(int(c), MONTHS[a.lower()[:3]], int(b)), "month-name first"
        if b.lower()[:3] in MONTHS:      # 26 Nov 2026
            return datetime(int(c), MONTHS[b.lower()[:3]], int(a)), "month-name second"
    raise ValueError(f"unrecognized date: {text!r}")

for s in ("2026-11-26", "2026-11-26 14:30", "Nov 26, 2026", "26 Nov 2026", "26/11/2026"):
    try:
        value, how = parse_user_date(s)
        print(f"{s!r:20s} -> {value}   (via {how})")
    except ValueError as e:
        print(f"{s!r:20s} -> rejected: {e}")

from datetime import date

def age_on(born, on):
    years = on.year - born.year
    try:
        birthday_this_year = born.replace(year=on.year)
    except ValueError:
        birthday_this_year = born.replace(year=on.year, day=28)  # policy choice!
    if on < birthday_this_year:
        years -= 1
    return years

born = date(2000, 2, 29)
for on in (date(2026, 2, 27), date(2026, 2, 28), date(2026, 3, 1), date(2028, 2, 29)):
    print(f"on {on}: age {age_on(born, on)}")

import calendar
from datetime import date, timedelta

def last_day(year, month):
    return date(year, month, calendar.monthrange(year, month)[1])

def last_weekday(year, month, weekday):  # Mon=0 .. Sun=6
    d = last_day(year, month)
    return d - timedelta(days=(d.weekday() - weekday) % 7)

for month in (1, 2, 3):
    print(f"2026-{month:02d}: last day {last_day(2026, month)}, last Friday {last_weekday(2026, month, 4)}")

from datetime import datetime, timezone

def overlaps(a_start, a_end, b_start, b_end):
    return a_start < b_end and b_start < a_end

def at(hour):
    return datetime(2026, 12, 5, hour, 0, tzinfo=timezone.utc)

cases = [
    ("disjoint, a first ", at(9), at(10), at(11), at(12), False),
    ("disjoint, b first ", at(11), at(12), at(9), at(10), False),
    ("partial overlap   ", at(9), at(11), at(10), at(12), True),
