from datetime import datetime, timezone

def at(hour, minute=0):
    return datetime(2026, 12, 5, hour, minute, tzinfo=timezone.utc)

def free_gaps(busy, day_start, day_end):
    gaps, cursor = [], day_start
    for start, end in sorted(busy):
        if start > cursor:
            gaps.append((cursor, start))
        cursor = max(cursor, end)
    if cursor < day_end:
        gaps.append((cursor, day_end))
    return gaps

busy = [(at(9), at(10)), (at(9, 30), at(11)), (at(13), at(14))]  # note the overlap
for start, end in free_gaps(busy, at(8), at(17)):
    print("free:", start.strftime("%H:%M"), "->", end.strftime("%H:%M"))

from datetime import datetime, timezone

def at(hour):
    return datetime(2026, 12, 5, hour, 0, tzinfo=timezone.utc)

def merge(intervals):
    merged = []
    for start, end in sorted(intervals):
        if merged and start <= merged[-1][1]:
            last_start, last_end = merged[-1]
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))
    return merged

bookings = [(at(11), at(12)), (at(9), at(10)), (at(9, ), at(11)), (at(14), at(15)), (at(12), at(13))]
for start, end in merge(bookings):
    print("busy:", start.strftime("%H:%M"), "->", end.strftime("%H:%M"))

from datetime import date

def same_date_next_year(d):
    try:
        return d.replace(year=d.year + 1)
    except ValueError:
        return d.replace(year=d.year + 1, day=28)   # documented policy

for start in (date(2028, 2, 29), date(2026, 11, 26), date(2026, 12, 31)):
    print(f"{start} -> {same_date_next_year(start)}")

